INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'In which position should the steering wheel normally be held according to the manual?', 'Both hands in the ten-to-two position', 'One hand at six o’clock', 'Both hands outside the vehicle', 'One hand on the gear lever', 'A', 'The manual specifies both hands in the ten-to-two position unless changing gears or giving hand signals.', '/testmate/assets/quiz/vehicle_controls/page_14_15.png', 'image', '3');
