INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 1 indicate?', 'Parking area reserved for emergency service vehicles', 'When displayed below a regulatory sign the regulatory sign applies only to motor cars or any other motor vehicle indi- cated on the sign', 'Stop your vehicle with its front end in line with the sign and do not proceed until it is safe to do so.', 'Public road or portion of road is reserved for minibuses', 'C', 'Stop your vehicle with its front end in line with the sign and do not proceed until it is safe to do so.', '/testmate/assets/quiz/regulatory_signs/sign_1.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 2 indicate?', 'When displayed below a parking reservation sign, the use of the parking area is subject to payment at a pay station', 'Road is set aside for pedal cycles and pedestrians only', 'Road is set aside for animal-drawn vehicles only', 'If you wish to proceed straight-on or to the right at the junction ahead, you shall act as for STOP sign; if you want to proceed to the left at the junction ahead, you shall yield right of way to all traffic, from the right (both vehicular and pedestrian), on the road which is joined by the road on which you are travelling where such traffic is so close as to constitute a danger or potential danger.', 'D', 'If you wish to proceed straight-on or to the right at the junction ahead, you shall act as for STOP sign; if you want to proceed to the left at the junction ahead, you shall yield right of way to all traffic, from the right (both vehicular and pedestrian), on the road which is joined by the road on which you are travelling where such traffic is so close as to constitute a danger or potential danger.', '/testmate/assets/quiz/regulatory_signs/sign_2.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 3 indicate?', 'Right-hand portion of public road is reserved for buses', 'Road is set aside for goods vehicles only', 'The use of a public road or portion of public road by drivers of vehicles is restricted to vehicles of a mass that exceeds that indicated in tonnes by means of a number only and that the driver of such a vehicle shall only use the public road or portion of public road designated by the sign. The value indicated in tonnes is the equivalent of the gross vehicle mass (GVM) or gross combination mass (GCM) of the vehicle in kilograms.', 'If you are approaching a 4 Way Stop sign, you shall stop such vehicle, and not proceed into the junction until every vehicle which has stopped at any other STOP LINE marking at such junction first, and which would, in the normal course of events, cross the path of your vehicle, has cleared the junction. In short, stop and than 1st come, 1st go!', 'D', 'If you are approaching a 4 Way Stop sign, you shall stop such vehicle, and not proceed into the junction until every vehicle which has stopped at any other STOP LINE marking at such junction first, and which would, in the normal course of events, cross the path of your vehicle, has cleared the junction. In short, stop and than 1st come, 1st go!', '/testmate/assets/quiz/regulatory_signs/sign_3.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 4 indicate?', 'Pass only to the left-hand side, as indicated by the arrow, of an obstacle in the road on which the sign has been placed.', 'YOU SHALL NOT ExCEED THE SPEED LIMIT indicated in kilometers per hour, by means of a number on such sign, beyond such sign.', 'Bus and minibus lane BEGINS and is reserved for buses and minibuses', 'This sign is used by temporary scholar patrols or for other temporary use, such as a police road block. Stop-and-Go sign indicates to you that you shall act as for Stop sign when “STOP” is displayed and; if “GO” is displayed, you shall proceed with caution.', 'D', 'This sign is used by temporary scholar patrols or for other temporary use, such as a police road block. Stop-and-Go sign indicates to you that you shall act as for Stop sign when “STOP” is displayed and; if “GO” is displayed, you shall proceed with caution.', '/testmate/assets/quiz/regulatory_signs/sign_4.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 5 indicate?', 'Drivers of vehicles with an axle massload in excess of the mass indicated in tonnes by means of a number on such sign, shall not proceed beyond such sign on a public road.', 'Drivers of midi-buses shall NOT proceed beyond such sign.', 'Right-hand portion of public road is reserved for authorised passenger transport vehicles', 'Yield right-of-way to all traffic on the road which is joined by the road on which you are travelling; or rail traffic on the railway line which is crossed by the road on which you are travelling, where such traffic is so close as to constitute a danger or potential danger.', 'D', 'Yield right-of-way to all traffic on the road which is joined by the road on which you are travelling; or rail traffic on the railway line which is crossed by the road on which you are travelling, where such traffic is so close as to constitute a danger or potential danger.', '/testmate/assets/quiz/regulatory_signs/sign_5.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 6 indicate?', 'When displayed below a regulatory sign the regulatory sign applies during the day', 'When displayed below a regulatory sign the regulatory sign applies to vehicles with a gross vehicle mass (GVM) exceeding the mass indicated in tonnes by the number on the exclusive secondary sign', 'If you are approaching such a sign you shall yield right-of-way to pedestrians crossing the public road, or waiting to cross the public road.', 'Parking area reserved for goods vehicles', 'C', 'If you are approaching such a sign you shall yield right-of-way to pedestrians crossing the public road, or waiting to cross the public road.', '/testmate/assets/quiz/regulatory_signs/sign_6.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 7 indicate?', 'Drivers of vehicles with a mass in excess of the mass indicated in tones, by means of a number on the sign, shall not proceed beyond such sign on a public road. The value indicated in tones is the gross vehicle mass (GVM) or gross combination mass (GCM) of the vehicle', 'If you wish to proceed straight-on or to the right at the junction ahead, you shall act as for STOP sign; if you want to proceed to the left at the junction ahead, you shall yield right of way to all traffic, from the right (both vehicular and pedestrian), on the road which is joined by the road on which you are travelling where such traffic is so close as to constitute a danger or potential danger.', 'If you are approaching a mini circle you shall yield right of way to any vehicle which will cross any YIELD LINE at such junction before you, and which, in the normal course of events, will cross the path of your vehicle. You shall move in a clockwise direction in such junction and attempt not to encroach on the mini circle.', 'Bus and midibus lane BEGINS and is reserved for buses and midibuses', 'C', 'If you are approaching a mini circle you shall yield right of way to any vehicle which will cross any YIELD LINE at such junction before you, and which, in the normal course of events, will cross the path of your vehicle. You shall move in a clockwise direction in such junction and attempt not to encroach on the mini circle.', '/testmate/assets/quiz/regulatory_signs/sign_7.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 8 indicate?', 'Public road or portion of road is reserved for vehicles conveying dangerous goods', 'The entry of all vehicular traffic is prohibited.', 'Public road or portion of road is reserved for motor cars', 'Public road or portion of road is reserved for construction vehicles', 'B', 'The entry of all vehicular traffic is prohibited.', '/testmate/assets/quiz/regulatory_signs/sign_8.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 9 indicate?', 'Proceed left (direction indicated by the arrow).', 'Public road or portion of road is reserved for goods vehicles with a gross vehicle mass (GVM) or gross combination mass (GCM) exceeding the mass in tonnes on sign', 'Bus and midibus lane BEGINS and is reserved for buses and midibuses', 'Drivers of animal drawn vehicles shall NOT proceed beyond such sign.', 'A', 'Proceed left (direction indicated by the arrow).', '/testmate/assets/quiz/regulatory_signs/sign_9.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 10 indicate?', 'Public road or portion of road is reserved for emergency service vehicles', 'Proceed right (direction indicated by the arrow).', 'Drivers of delivery vehicles shall NOT proceed beyond such sign.', 'No hawkers are allowed within 75 metres on either side of such sign.', 'B', 'Proceed right (direction indicated by the arrow).', '/testmate/assets/quiz/regulatory_signs/sign_10.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 11 indicate?', 'Proceed straight (direction indicated by the arrow).', 'Public road or portion of road is reserved for goods vehicles with a gross vehicle mass (GVM) or gross combination mass (GCM) exceeding the mass in tonnes on sign', 'Road is set aside for minibuses only', 'Parking area reserved for high occupancy vehicles', 'A', 'Proceed straight (direction indicated by the arrow).', '/testmate/assets/quiz/regulatory_signs/sign_11.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 12 indicate?', 'Drivers shall not sound their vehicle sounding device or hooter for 100m after passing sign, AND drivers shall not drive a vehicle beyond such sign, if such vehicle is emitting noise in excess of noise levels prescribed.', 'The pedestrian priority sign is to indicate to drivers of vehicles that only pedestrians shall be permitted in an area set aside as a pedestrian precinct marked by such signs and the contemplated vehicles such as loading goods, maintenance or emergency vehicles. In cases where drivers of these exempted vehicles pass beyond the point where such sign is displayed they shall yield right-of-way to all pedestrians who are crossing or who are about to cross their way; observe a maximum speed of 15 kilometres per hour unless another speed limit is indicated by another sign and, if delivering or loading goods, shall do so in places specifically marked for such purpose in such area.', 'Portion of public road is a high occupancy vehicle lane and is reserved for high occupancy vehicles', 'Left-hand portion of public road is reserved for authorised passenger transport vehicles', 'B', 'The pedestrian priority sign is to indicate to drivers of vehicles that only pedestrians shall be permitted in an area set aside as a pedestrian precinct marked by such signs and the contemplated vehicles such as loading goods, maintenance or emergency vehicles. In cases where drivers of these exempted vehicles pass beyond the point where such sign is displayed they shall yield right-of-way to all pedestrians who are crossing or who are about to cross their way; observe a maximum speed of 15 kilometres per hour unless another speed limit is indicated by another sign and, if delivering or loading goods, shall do so in places specifically marked for such purpose in such area.', '/testmate/assets/quiz/regulatory_signs/sign_12.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 13 indicate?', 'Parking area reserved for high occupancy vehicles', 'Portion of public road is a bus lane and is reserved for buses', 'Road is set aside for pedestrians only', 'If you are approaching such a sign, you shall yield right-of-way to all oncoming traffic and shall proceed only when it is safe to do so.', 'D', 'If you are approaching such a sign, you shall yield right-of-way to all oncoming traffic and shall proceed only when it is safe to do so.', '/testmate/assets/quiz/regulatory_signs/sign_13.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 14 indicate?', 'Public road or portion of road is reserved for police vehicles', 'Road is set aside for taxis only', 'Maintain or exceed the minimum speed indicated in kilometres per hour by means of a number on the sign.', 'Road is reserved for buses only', 'C', 'Maintain or exceed the minimum speed indicated in kilometres per hour by means of a number on the sign.', '/testmate/assets/quiz/regulatory_signs/sign_14.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 15 indicate?', 'The use of a public road or portion of public road by drivers of vehicles is restricted to vehicles of a mass that exceeds that indicated in tonnes by means of a number only and that the driver of such a vehicle shall only use the public road or portion of public road designated by the sign. The value indicated in tonnes is the equivalent of the gross vehicle mass (GVM) or gross combination mass (GCM) of the vehicle in kilograms.', 'Maintain or exceed the minimum speed indicated in kilometres per hour by means of a number on the sign.', 'Road is set aside for midi-buses only', 'Right-hand portion of public road is reserved for buses and minibuses', 'A', 'The use of a public road or portion of public road by drivers of vehicles is restricted to vehicles of a mass that exceeds that indicated in tonnes by means of a number only and that the driver of such a vehicle shall only use the public road or portion of public road designated by the sign. The value indicated in tonnes is the equivalent of the gross vehicle mass (GVM) or gross combination mass (GCM) of the vehicle in kilograms.', '/testmate/assets/quiz/regulatory_signs/sign_15.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 16 indicate?', 'Area reserved for parking for a maximum period as indicated on the sign', 'Public road or portion of road is reserved for goods vehicles with a gross vehicle mass (GVM) or gross combination mass (GCM) exceeding the mass in tonnes on sign', 'The use of a public road or portion of public road by drivers of vehicles is restricted to vehicles of a mass that exceeds that indicated in tonnes by means of a number only and that the driver of such a vehicle shall only use the public road or portion of public road designated by the sign. The value indicated in tonnes is the equivalent of the gross vehicle mass (GVM) or gross combination mass (GCM) of the vehicle in kilograms.', 'Pass only to the left-hand side, as indicated by the arrow, of an obstacle in the road on which the sign has been placed.', 'D', 'Pass only to the left-hand side, as indicated by the arrow, of an obstacle in the road on which the sign has been placed.', '/testmate/assets/quiz/regulatory_signs/sign_16.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 17 indicate?', 'Proceed only in the direction indicated by the arrow on such sign.', 'Road is set aside for Pedal cycles only', 'Road is set aside for animal-drawn vehicles only', 'Portion of public road is a high occupancy vehicle lane and is reserved for high occupancy vehicles', 'A', 'Proceed only in the direction indicated by the arrow on such sign.', '/testmate/assets/quiz/regulatory_signs/sign_17.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 18 indicate?', 'Proceed only in direction indicated by the arrow on such sign, at the junction ahead.', 'When displayed below a regulatory sign the restriction indicated on the exclusive secondary sign applies to the direction indicated by the arrow', 'When displayed below a regulatory sign the regulatory sign applies only to motor cars or any other motor vehicle indi- cated on the sign', 'Right-hand portion of public road is reserved for buses', 'A', 'Proceed only in direction indicated by the arrow on such sign, at the junction ahead.', '/testmate/assets/quiz/regulatory_signs/sign_18.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 19 indicate?', 'Pedal cycles shall NOT proceed beyond such sign.', 'Public road or portion of road is reserved for high occupancy vehicles', 'Road is set aside for pedestrians only', 'Road is set aside for Pedal cycles only', 'C', 'Road is set aside for pedestrians only', '/testmate/assets/quiz/regulatory_signs/sign_19.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 20 indicate?', 'Drivers of minibuses shall NOT proceed beyond such sign.', 'The driver no longer needs to comply with the regulatory message', 'Road is set aside for Pedal cycles only', 'When displayed below a regulatory sign the restriction indicated on the exclusive secondary sign applies to the direction indicated by the arrow', 'C', 'Road is set aside for Pedal cycles only', '/testmate/assets/quiz/regulatory_signs/sign_20.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 21 indicate?', 'Road is set aside for pedal cycles and pedestrians only', 'When displayed below a regulatory sign the regulatory sign applies only during the period of time on a weekday and a different period of time on a Saturday as indicated on the exclusive secondary sign', 'Area reserved for parking for a maximum period as indicated on the sign', 'Drivers of unauthorised vehicles shall not proceed beyond such sign.', 'A', 'Road is set aside for pedal cycles and pedestrians only', '/testmate/assets/quiz/regulatory_signs/sign_21.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 22 indicate?', 'Road is set aside for pedal cycles and pedestrians only', 'Road is set aside for goods vehicles only', 'Road is set aside for abnormal vehicles only', 'Public road or portion of road is reserved for motorcycles', 'A', 'Road is set aside for pedal cycles and pedestrians only', '/testmate/assets/quiz/regulatory_signs/sign_22.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 23 indicate?', 'Road is set aside for motor cyclists only', 'Driver of a vehicle towing another vehicle shall NOT proceed beyond such sign.', 'A driver may not enter the area driving a vehicle with a gross vehicle mass exceeding 3500kg or a vehicle with more than 10 seats for passengers except for local access or delivery; must yield right of way to pedestrians and children; and may not drive faster than 30km/h or as indicated by a sign', 'When displayed below a regulatory sign the restriction indicated on the exclusive secondary sign applies to the direction indicated by the arrow', 'A', 'Road is set aside for motor cyclists only', '/testmate/assets/quiz/regulatory_signs/sign_23.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 24 indicate?', 'Road is set aside for motor cars only', 'Public road or portion of road is reserved for construction vehicles', 'Yield right-of-way to all traffic on the road which is joined by the road on which you are travelling; or rail traffic on the railway line which is crossed by the road on which you are travelling, where such traffic is so close as to constitute a danger or potential danger.', 'The pedestrian priority sign is to indicate to drivers of vehicles that only pedestrians shall be permitted in an area set aside as a pedestrian precinct marked by such signs and the contemplated vehicles such as loading goods, maintenance or emergency vehicles. In cases where drivers of these exempted vehicles pass beyond the point where such sign is displayed they shall yield right-of-way to all pedestrians who are crossing or who are about to cross their way; observe a maximum speed of 15 kilometres per hour unless another speed limit is indicated by another sign and, if delivering or loading goods, shall do so in places specifically marked for such purpose in such area.', 'A', 'Road is set aside for motor cars only', '/testmate/assets/quiz/regulatory_signs/sign_24.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 25 indicate?', 'When displayed below a regulatory sign the regulatory sign applies during the day', 'Drivers of vehicles with a mass in excess of the mass indicated in tones, by means of a number on the sign, shall not proceed beyond such sign on a public road. The value indicated in tones is the gross vehicle mass (GVM) or gross combination mass (GCM) of the vehicle', 'Road is set aside for taxis only', 'Portion of public road is reserved as a minibus stop for the minibus of the organization indicated on the sign by means of a crest , logo or other device', 'C', 'Road is set aside for taxis only', '/testmate/assets/quiz/regulatory_signs/sign_25.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 26 indicate?', 'Right-hand portion of public road is reserved for high occupancy vehicles', 'Drivers shall not sound their vehicle sounding device or hooter for 100m after passing sign, AND drivers shall not drive a vehicle beyond such sign, if such vehicle is emitting noise in excess of noise levels prescribed.', 'Public road or portion of road is reserved for taxis', 'Road is set aside for minibuses only', 'D', 'Road is set aside for minibuses only', '/testmate/assets/quiz/regulatory_signs/sign_26.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 27 indicate?', 'Road is set aside for all classes of buses and minibuses only', 'Road is set aside for Pedal cycles only', 'Drivers of vehicles with a mass in excess of the mass indicated in tones, by means of a number on the sign, shall not proceed beyond such sign on a public road. The value indicated in tones is the gross vehicle mass (GVM) or gross combination mass (GCM) of the vehicle', 'Road is set aside for midi-buses only', 'D', 'Road is set aside for midi-buses only', '/testmate/assets/quiz/regulatory_signs/sign_27.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 28 indicate?', 'Drivers of tour buses shall NOT proceed beyond such sign.', 'Drivers of vehicles on a public road shall not proceed beyond the sign or drive under a height gauge or structure to which the sign is attached unless the height of the vehicle, including any load thereon, and, in the case of a height gauge, any radio antenna attached to the vehicle, is less than the clearance height indicated in meters by means of a number on such sign.', 'Horses and their riders, whether mounted on the horses or leading them, shall NOT proceed beyond such sign.', 'Road is set aside for buses only', 'D', 'Road is set aside for buses only', '/testmate/assets/quiz/regulatory_signs/sign_28.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 29 indicate?', 'Right-hand portion of public road is reserved for high occupancy vehicles', 'Public road or portion of road is reserved for taxis', 'Road is set aside for delivery vehicles only', 'Bus, midibus and minibus lane BEGINS and is reserved for buses, midibuses and minibuses', 'C', 'Road is set aside for delivery vehicles only', '/testmate/assets/quiz/regulatory_signs/sign_29.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 30 indicate?', 'Public road or portion of road is reserved for construction vehicles', 'Road is set aside for goods vehicles only', 'Drivers of vehicles with a mass in excess of the mass indicated in tones, by means of a number on the sign, shall not proceed beyond such sign on a public road. The value indicated in tones is the gross vehicle mass (GVM) or gross combination mass (GCM) of the vehicle', 'When displayed below a regulatory sign the regulatory sign applies to vehicles with a gross vehicle mass (GVM) exceeding the mass indicated in tonnes by the number on the exclusive secondary sign', 'B', 'Road is set aside for goods vehicles only', '/testmate/assets/quiz/regulatory_signs/sign_30.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 170 indicate?', 'The sign warns you of the likelihood of the presence of low flying aircraft in the vicinity of the road, the sudden noise of which may constitute a hazard.', 'The sign warns you about a Stop sign which is about 150m ahead', 'The sign warns you about a crossroad ahead.', 'The sign warns you that you should be more careful due to sand ahead', 'C', 'The sign warns you about a crossroad ahead.', '/testmate/assets/quiz/warning_signs/sign_170.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 171 indicate?', 'The sign warns you that the road ahead is diverted to the right or left owing to a sudden change of direction.', 'The sign warns you of the possible presence of horses in the road ahead which are being ridden or led by their riders and which may constitute a hazard if disturbed by passing traffic.', 'The sign warns you of a hazard ahead, by means of an intermittent flashing yellow circular light within the warning sign.', 'The sign warns you about a crossroad ahead and that you are travelling on an approach that has priority over intersecting approaches.', 'D', 'The sign warns you about a crossroad ahead and that you are travelling on an approach that has priority over intersecting approaches.', '/testmate/assets/quiz/warning_signs/sign_171.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 172 indicate?', 'The sign warns you about a sharp curve ahead', 'The sign warns you about the possible presence of elephants on the public road ahead.', 'The sign warns you of abnormally slippery conditions on the road ahead for which a considerable reduction in speed is necessary.', 'The sign warns you about a crossroad ahead and that you are travelling on an approach that DOES NOT has priority over in- tersecting approaches.', 'D', 'The sign warns you about a crossroad ahead and that you are travelling on an approach that DOES NOT has priority over in- tersecting approaches.', '/testmate/assets/quiz/warning_signs/sign_172.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 173 indicate?', 'The sign warns you about the presence of a STOP sign ahead', 'The sign warns you about a sharp u-shaped bend ahead', 'The sign warns you that the next crossroad carries two-way traffic', 'The sign warns you about a T-Junction ahead where traffic is required to make a sharp or acute turn either to the left or to the right.', 'D', 'The sign warns you about a T-Junction ahead where traffic is required to make a sharp or acute turn either to the left or to the right.', '/testmate/assets/quiz/warning_signs/sign_173.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 174 indicate?', 'The sign warns you about a crossroad ahead and that you are travelling on an approach that DOES NOT has priority over in- tersecting approaches.', 'The sign warns you about a grader working on the road ahead', 'The sign warns you about a hazardous change in the surface of the road', 'The sign warns you about a skew T-junction ahead where traf- fic is required to make a sharp or acute turn either to the left or to the right.', 'D', 'The sign warns you about a skew T-junction ahead where traf- fic is required to make a sharp or acute turn either to the left or to the right.', '/testmate/assets/quiz/warning_signs/sign_174.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 175 indicate?', 'The sign warns you that due to the steep downhill section of road ahead, heavy vehicles may be travelling very slowly in a low gear, which combined with reduced visibility conditions due to road curvature or weather, constitutes a potential hazard.', 'The sign warns you about a traffic officer ahead temporarily controlling traffic', 'The sign warns you about a side road junction ahead where traffic might enter the road from the left.', 'The sign warns you about construction vehicles that regularly cross or enter the road ahead from the left or right', 'C', 'The sign warns you about a side road junction ahead where traffic might enter the road from the left.', '/testmate/assets/quiz/warning_signs/sign_175.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 176 indicate?', 'The sign warns you on a one-way road that the road ahead carries traffic in both directions', 'The sign warns you about the presence of a traffic control signal ahead', 'The sign warns you about a staggered junction ahead where traffic might enter the road from the right or left.', 'The sign warns you about the possible presence of farm animals either crossing or straying in the road ahead.', 'C', 'The sign warns you about a staggered junction ahead where traffic might enter the road from the right or left.', '/testmate/assets/quiz/warning_signs/sign_176.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 177 indicate?', 'The sign warns you about the presence of a YIELD sign ahead.', 'The sign warns you about a sharp junction from the left is ahead', 'The sign warns you of presence of police at a temporary stop sign ahead or of an accident site or similar occurrence where the police are present', 'The sign warns you that the width of the structure on the road ahead is less than 5m and that you shall stop at the entrance thereto if a vehicle approaching from the opposite direction is already on the structure, or so close thereto as to constitute a danger.', 'B', 'The sign warns you about a sharp junction from the left is ahead', '/testmate/assets/quiz/warning_signs/sign_177.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 178 indicate?', 'The sign warns you about a sharp junction from the right is ahead', 'The sign warns you of temporary obstruction or alteration in the road alignment to the left or right.', 'The sign warns you about a mini circle or traffic circle ahead', 'The sign warns you about loose stones or gravel on the road ahead', 'A', 'The sign warns you about a sharp junction from the right is ahead', '/testmate/assets/quiz/warning_signs/sign_178.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 179 indicate?', 'The sign warns you of speed humps on the road ahead which require a reduction in speed.', 'The sign warns you about a Y-junction ahead and that the road forms the stem of the Y.', 'The sign warns you about a series of curves in the road ahead starting with a curve to the left or right', 'The sign warns you about an overhead obstruction above the road.', 'B', 'The sign warns you about a Y-junction ahead and that the road forms the stem of the Y.', '/testmate/assets/quiz/warning_signs/sign_179.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 180 indicate?', 'The sign warns you about a two-way road that is ending and that a one-way road is about to be entered at which point a physical median island will commence.', 'The sign warns you about a sharp junction from the right is ahead', 'The sign warns you that you should be more careful due to sand ahead', 'The sign warns you about the presence of a STOP sign ahead', 'A', 'The sign warns you about a two-way road that is ending and that a one-way road is about to be entered at which point a physical median island will commence.', '/testmate/assets/quiz/warning_signs/sign_180.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 181 indicate?', 'The sign warns you of the likelihood of the presence of low flying aircraft in the vicinity of the road, the sudden noise of which may constitute a hazard.', 'The sign warns you that there is a junction of two one-way roads ahead and that a road with two-way traffic is about to be entered.', 'The sign warns you about a sharp curve ahead', 'The sign warns you of an obstruction or alteration in the road alignment to the left or right.', 'B', 'The sign warns you that there is a junction of two one-way roads ahead and that a road with two-way traffic is about to be entered.', '/testmate/assets/quiz/warning_signs/sign_181.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 182 indicate?', 'The sign warns you about the clearance of height gauge located ahead of a railway crossing over which overhead electrical power cables are installed; or an overhead structure is restricted in metres by the number indicated on the sign.', 'The sign warns you of presence of police at a temporary stop sign ahead or of an accident site or similar occurrence where the police are present', 'The sign warns you about a Y-junction ahead and that the road forms the stem of the Y.', 'The sign warns you about a mini circle or traffic circle ahead', 'D', 'The sign warns you about a mini circle or traffic circle ahead', '/testmate/assets/quiz/warning_signs/sign_182.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 183 indicate?', 'The sign warns you that a portion of the road is temporarily closed to traffic.', 'The sign warns you of presence of an accident ahead', 'The sign warns you about a gentle curve ahead', 'The sign warns you about the possible presence of pedestrians ahead.', 'C', 'The sign warns you about a gentle curve ahead', '/testmate/assets/quiz/warning_signs/sign_183.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 184 indicate?', 'The sign warns you about a sharp curve ahead', 'The sign warns you about the material of the shoulder of the road that is softer than would be reasonably expected and constitute a hazard to anyone wishing to pull off road', 'The sign warns you that the road ahead is diverted to the right or left owing to a sudden change of direction.', 'The sign warns you that there are potentially live overhead electrical power cables ahead and that these may constitute a hazard if contacted by a vehicle or any vertical projection carried by the road user.', 'A', 'The sign warns you about a sharp curve ahead', '/testmate/assets/quiz/warning_signs/sign_184.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 185 indicate?', 'The sign warns you about temporary road construction, maintenance or related work in progress ahead', 'The sign warns you of a hazard ahead, by means of an intermittent flashing yellow circular light within the warning sign.', 'The sign warns you about a Y-junction ahead and that the road forms the stem of the Y.', 'The sign warns you about a sharp u-shaped bend ahead', 'D', 'The sign warns you about a sharp u-shaped bend ahead', '/testmate/assets/quiz/warning_signs/sign_185.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 186 indicate?', 'The sign warns you about a series of curves in the road ahead starting with a curve to the left or right', 'The sign warns you about scholar patrol temporarily operating ahead', 'The sign warns you about a marked pedestrian crossing ahead', 'The sign warns you about a hazardous change in the surface of the road', 'A', 'The sign warns you about a series of curves in the road ahead starting with a curve to the left or right', '/testmate/assets/quiz/warning_signs/sign_186.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 187 indicate?', 'The sign warns you about a combination of two sharp curves in opposite directions ahead', 'The sign warns you that there is a dip or ridge in the road or that the road surface is generally uneven or potholed.', 'The sign warns you of the possible presence of horses in the road ahead which are being ridden or led by their riders and which may constitute a hazard if disturbed by passing traffic.', 'The sign warns you that due to the steep downhill section of road ahead, heavy vehicles may be travelling very slowly in a low gear, which combined with reduced visibility conditions due to road curvature or weather, constitutes a potential hazard.', 'A', 'The sign warns you about a combination of two sharp curves in opposite directions ahead', '/testmate/assets/quiz/warning_signs/sign_187.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 188 indicate?', 'The sign warns you that the road ahead is diverted to the right or left owing to a sudden change of direction.', 'The sign warns you of the possibility of reduced visibility ahead due to mist, fog or smoke which constitutes a hazard and may require a considerable reduction in speed.', 'The sign warns you on a one-way road that the road ahead carries traffic in both directions', 'The sign warns you that the road ahead narrows from both sides.', 'C', 'The sign warns you on a one-way road that the road ahead carries traffic in both directions', '/testmate/assets/quiz/warning_signs/sign_188.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 189 indicate?', 'The sign warns you of the possible presence of horses in the road ahead which are being ridden or led by their riders and which may constitute a hazard if disturbed by passing traffic.', 'The sign warns you of a drift ahead which may contain water, flash floods after thunder storms, rock outcrops or loose material or which may represent a hazardous depression in the road when dry.', 'The sign warns you that the next crossroad carries two-way traffic', 'The sign warns you about temporary road construction, maintenance or related work in progress ahead', 'C', 'The sign warns you that the next crossroad carries two-way traffic', '/testmate/assets/quiz/warning_signs/sign_189.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 190 indicate?', 'The sign warns you about a portion of the road which is reduced in width by a full lane from the right or left side', 'The sign warns you of abnormally slippery conditions on the road ahead for which a considerable reduction in speed is necessary.', 'The sign warns you that the width of road is reduced over short distance at a bridge on the road ahead.', 'The sign warns you that tractors or other slow moving agricultural vehicle regularly cross or enter the road ahead.', 'A', 'The sign warns you about a portion of the road which is reduced in width by a full lane from the right or left side', '/testmate/assets/quiz/warning_signs/sign_190.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 191 indicate?', 'The sign warns you about other vehicles that may enter road ahead from driveways on the right or left or both sides in such a manner that due to restricted sight they may constitute a hazard', 'The sign warns you that there is a dip or ridge in the road or that the road surface is generally uneven or potholed.', 'The sign warns you about the possibility of severe crosswinds ahead which are capable of deflecting a vehicle from its path.', 'The sign warns you that there is a junction of two one-way roads ahead and that a road with two-way traffic is about to be entered.', 'A', 'The sign warns you about other vehicles that may enter road ahead from driveways on the right or left or both sides in such a manner that due to restricted sight they may constitute a hazard', '/testmate/assets/quiz/warning_signs/sign_191.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 192 indicate?', 'The sign warns you about the presence of a traffic control signal ahead', 'The sign warns you of presence of police at a temporary stop sign ahead or of an accident site or similar occurrence where the police are present', 'The sign warns you about a combination of two sharp curves in opposite directions ahead', 'The sign warns you that the road does not continue beyond the sign.', 'A', 'The sign warns you about the presence of a traffic control signal ahead', '/testmate/assets/quiz/warning_signs/sign_192.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 193 indicate?', 'The sign warns you about the presence of a STOP sign ahead', 'The sign warns you that the road ahead narrows from the right side only.', 'The sign warns you of a hazard ahead, by means of an intermittent flashing yellow circular light within the warning sign.', 'The sign warns you about an overhead obstruction above the road.', 'A', 'The sign warns you about the presence of a STOP sign ahead', '/testmate/assets/quiz/warning_signs/sign_193.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 194 indicate?', 'The sign warns you about the possible presence of children near schools, playgrounds, sports field or other places ahead.', 'The sign warns you about an overhead obstruction above the road.', 'The sign warns you about the presence of a YIELD sign ahead.', 'The sign warns you that a motor gate is ahead on the right side of the road.', 'C', 'The sign warns you about the presence of a YIELD sign ahead.', '/testmate/assets/quiz/warning_signs/sign_194.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 195 indicate?', 'The sign warns you about an overhead obstruction above the road.', 'The sign warns you that there is a dip or ridge in the road or that the road surface is generally uneven or potholed.', 'The sign warns you of the likelihood of the presence of low flying aircraft in the vicinity of the road, the sudden noise of which may constitute a hazard.', 'The sign warns you about a traffic officer ahead temporarily controlling traffic', 'D', 'The sign warns you about a traffic officer ahead temporarily controlling traffic', '/testmate/assets/quiz/warning_signs/sign_195.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 196 indicate?', 'The sign warns you that the road ahead is diverted to the right or left owing to a sudden change of direction.', 'The sign warns you of abnormally slippery conditions on the road ahead for which a considerable reduction in speed is necessary.', 'The sign warns you of presence of an accident ahead', 'The sign warns you about scholar patrol temporarily operating ahead', 'D', 'The sign warns you about scholar patrol temporarily operating ahead', '/testmate/assets/quiz/warning_signs/sign_196.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 197 indicate?', 'The sign warns you about a series of curves in the road ahead starting with a curve to the left or right', 'The sign warns you of a hazard ahead, by means of an intermittent flashing yellow circular light within the warning sign.', 'The sign warns you about a Stop sign which is about 150m ahead', 'The sign warns you about a marked pedestrian crossing ahead', 'D', 'The sign warns you about a marked pedestrian crossing ahead', '/testmate/assets/quiz/warning_signs/sign_197.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 198 indicate?', 'The sign warns you about the possibility of severe crosswinds ahead which are capable of deflecting a vehicle from its path.', 'The sign warns you about construction vehicles that regularly cross or enter the road ahead from the left or right', 'The sign warns you about the possible presence of pedestrians ahead.', 'The sign warns you that the road surface on which you are travelling is about to change from asphalt or tar or concrete to gravel.', 'C', 'The sign warns you about the possible presence of pedestrians ahead.', '/testmate/assets/quiz/warning_signs/sign_198.png', 'image', '3');
