INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 429 indicate?', 'Demarcates traffic lanes for road users travelling on a road or portion of the road in the same direction', 'Do not drive in such a manner that the vehicle or any part of it crosses the line to the right of the line', 'Sign 429 (Stop line Stop the vehicle immediately behind the line. A road sign or signal indicating that the driver may proceed has preference over the marking. The word “stop” is omitted at intersections controlled by traffic signals and at pedestrian crossings.)', 'Right edge of road, do not drive to the right of the marking or cross to the right of the marking', 'C', 'Sign 429 (Stop line Stop the vehicle immediately behind the line. A road sign or signal indicating that the driver may proceed has preference over the marking. The word “stop” is omitted at intersections controlled by traffic signals and at pedestrian crossings.)', '/testmate/assets/quiz/road_markings/sign_429.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 430 indicate?', 'Indicates the direction of travel on a particular lane or road', 'Do not drive in such manner that the vehicle or any part of it crosses the marking or stop so that the vehicle or any part of it is on the marking', 'Gives additional guidance to a road user', 'Sign 430 (Yield line Indicates to the driver the point where to yield right of way to all traffic on public road or rail traffic joined by public road on which you are travelling)', 'D', 'Sign 430 (Yield line Indicates to the driver the point where to yield right of way to all traffic on public road or rail traffic joined by public road on which you are travelling)', '/testmate/assets/quiz/road_markings/sign_430.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 431 indicate?', 'Indicates the direction of travel on a particular lane or road', 'Right edge of road, do not drive to the right of the marking or cross to the right of the marking', 'Lane marked is for the use of vehicles as indicated by the symbol or as indicated by a reservation sign. For example in this case, disabled persons.', 'Sign 431 (Pedestrian Yield right of way, slow down or stop if need be to yield to crossing line pedestrians crossing the road within the pedestrian crossing when the pedestrian is on that portion of the road on which the vehicle is travelling or when the pedestrian is approaching so closely from the opposite half of the road as to be in danger)', 'D', 'Sign 431 (Pedestrian Yield right of way, slow down or stop if need be to yield to crossing line pedestrians crossing the road within the pedestrian crossing when the pedestrian is on that portion of the road on which the vehicle is travelling or when the pedestrian is approaching so closely from the opposite half of the road as to be in danger)', '/testmate/assets/quiz/road_markings/sign_431.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 432 indicate?', 'Escape road is ahead', 'An arrestor bed is ahead', 'Do not drive, park or stop a vehicle in the lane unless it is a vehicle of the class indicated by the symbol or a reservation sign', 'Sign 432 (Block pedestrian Yield right of way, slow down or stop if need be to yield to crossing pedestrians crossing the road within the pedestrian crossing when the pedestrian is on that portion of the road on which the vehicle is travelling or when the pedestrian is approaching so closely from the opposite half of the road as to be in danger)', 'D', 'Sign 432 (Block pedestrian Yield right of way, slow down or stop if need be to yield to crossing pedestrians crossing the road within the pedestrian crossing when the pedestrian is on that portion of the road on which the vehicle is travelling or when the pedestrian is approaching so closely from the opposite half of the road as to be in danger)', '/testmate/assets/quiz/road_markings/sign_432.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 433 indicate?', 'Do not drive in such a manner that the vehicle or any part of it crosses the marking or is on the right side of the marking', 'Right edge of road, do not drive to the right of the marking or cross to the right of the marking', 'Parking bay reserved for a vehicle transporting a person with a physical disability', 'Do not drive in such a manner that the vehicle or any part of it crosses the line to the right of the line', 'D', 'Do not drive in such a manner that the vehicle or any part of it crosses the line to the right of the line', '/testmate/assets/quiz/road_markings/sign_433.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 434 indicate?', 'Do not enter the box area in a junction if it is not possible to cross the area due to stationary vehicles blocking the way, but a vehicle turning to the left or to the right may enter the junction.', 'Indicates the direction of travel on a particular lane or road', 'Do not drive in such a manner that the vehicle or any part of it crosses the marking. The line is used between lanes of traffic travelling in the same direction.', 'Vehicles on the other side of the marking travel in the opposite direction', 'C', 'Do not drive in such a manner that the vehicle or any part of it crosses the marking. The line is used between lanes of traffic travelling in the same direction.', '/testmate/assets/quiz/road_markings/sign_434.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 435 indicate?', 'Do not stop the vehicle next to the line, where the line is bro- ken, during the time period indicated by an accompanying road sign', 'In an urban area, do not park the vehicle next to the line, where the line is broken, during the time period indicated by an accompanying road sign', 'Do not drive in such a manner that the vehicle or any part of it crosses the marking or is on the right side of the marking', 'Gives additional guidance to a road user when turning to the left or right in a junction, when a shift in a lane alignment occurs a junction, or to pedestrians when the position of a pedestrian crossing is not obvious in a junction', 'C', 'Do not drive in such a manner that the vehicle or any part of it crosses the marking or is on the right side of the marking', '/testmate/assets/quiz/road_markings/sign_435.png', 'image', '1');
