INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 440 indicate?', 'A driver approaching a traffic circle must yield right of way to any vehicle which will cross any yield line at the junction before him/her and which in the normal course of events will cross his/her path; you must travel in a clockwise direction and as far as possible avoid driving over the mini circle marking', 'Area marked is exclusively for the use of vehicles as indicated by the symbol', 'Indicates the direction of travel on a particular lane or road', 'Motorcycles may not proceed beyond the marking', 'B', 'Area marked is exclusively for the use of vehicles as indicated by the symbol', '/testmate/assets/quiz/road_markings/sign_440.png', 'image', '2');
