INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 443 indicate?', 'Do not cross the marking or bring the vehicle to a stop within the zig-zag zone except to yield right of way to pedestrians on the crossing, stop behind a vehicle or to obey a traffic signal', 'Do not drive, park or stop a vehicle in the lane unless it is a vehicle of the class indicated by the symbol or a reservation sign', 'Lane marked is for the use of vehicles as indicated by the symbol or as indicated by a reservation sign. For example in this case, a high-occupancy vehicle.', 'Right edge of road, do not drive to the right of the marking or cross to the right of the marking', 'A', 'Do not cross the marking or bring the vehicle to a stop within the zig-zag zone except to yield right of way to pedestrians on the crossing, stop behind a vehicle or to obey a traffic signal', '/testmate/assets/quiz/road_markings/sign_443.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 444 indicate?', 'Area marked is exclusively for the use of vehicles as indicated by the symbol', 'Gives additional guidance to a road user regarding the presence of kerbs on the kerb line of the road', 'Indicates the direction of travel on a particular lane or road', 'Do not enter the box area in a junction if it is not possible to cross the area due to stationary vehicles blocking the way, but a vehicle turning to the left or to the right may enter the junction.', 'D', 'Do not enter the box area in a junction if it is not possible to cross the area due to stationary vehicles blocking the way, but a vehicle turning to the left or to the right may enter the junction.', '/testmate/assets/quiz/road_markings/sign_444.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 445 indicate?', 'Do not stop the vehicle next to the line', 'Sign 430 (Yield line Indicates to the driver the point where to yield right of way to all traffic on public road or rail traffic joined by public road on which you are travelling)', 'Do not drive, park or stop a vehicle in the lane unless it is a vehicle of the class indicated by the symbol or a reservation sign', 'Escape road is ahead', 'A', 'Do not stop the vehicle next to the line', '/testmate/assets/quiz/road_markings/sign_445.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 446 indicate?', 'Do not stop the vehicle next to the line, where the line is bro- ken, during the time period indicated by an accompanying road sign', 'Sign 430 (Yield line Indicates to the driver the point where to yield right of way to all traffic on public road or rail traffic joined by public road on which you are travelling)', 'Do not drive in such a manner that the vehicle or any part of it crosses the marking. The line is used between lanes of traffic travelling in the same direction.', 'Left edge of road, do not drive to the left of the marking or cross to the left of the marking', 'A', 'Do not stop the vehicle next to the line, where the line is bro- ken, during the time period indicated by an accompanying road sign', '/testmate/assets/quiz/road_markings/sign_446.png', 'image', '2');
