INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 448 indicate?', 'Indicates the outer limits of a continuous portion of the road, and that those portions of a road outside the marking do not continue straight on', 'A driver approaching a traffic circle must yield right of way to any vehicle which will cross any yield line at the junction before him/her and which in the normal course of events will cross his/her path; you must travel in a clockwise direction and as far as possible avoid driving over the mini circle marking', 'In an urban area, do not park the vehicle next to the line, where the line is broken, during the time period indicated by an accompanying road sign', 'Escape road is ahead', 'C', 'In an urban area, do not park the vehicle next to the line, where the line is broken, during the time period indicated by an accompanying road sign', '/testmate/assets/quiz/road_markings/sign_448.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 449 indicate?', 'A driver approaching a traffic circle must yield right of way to any vehicle which will cross any yield line at the junction before him/her and which in the normal course of events will cross his/her path; you must travel in a clockwise direction and as far as possible avoid driving over the mini circle marking', 'Indicates the outer limits of a continuous portion of the road, and that those portions of a road outside the marking do not continue straight on', 'Mandatory direction arrow is ahead', 'Park within the demarcated parking bay, no part of the vehicle may be on any sidewalk', 'A', 'A driver approaching a traffic circle must yield right of way to any vehicle which will cross any yield line at the junction before him/her and which in the normal course of events will cross his/her path; you must travel in a clockwise direction and as far as possible avoid driving over the mini circle marking', '/testmate/assets/quiz/road_markings/sign_449.png', 'image', '3');
