INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 451 indicate?', 'Lane marked is for the use of vehicles as indicated by the symbol or as indicated by a reservation sign. For example in this case, a high-occupancy vehicle.', 'Sign 429 (Stop line Stop the vehicle immediately behind the line. A road sign or signal indicating that the driver may proceed has preference over the marking. The word “stop” is omitted at intersections controlled by traffic signals and at pedestrian crossings.)', 'Sign 431 (Pedestrian Yield right of way, slow down or stop if need be to yield to crossing line pedestrians crossing the road within the pedestrian crossing when the pedestrian is on that portion of the road on which the vehicle is travelling or when the pedestrian is approaching so closely from the opposite half of the road as to be in danger)', 'An arrestor bed is ahead', 'A', 'Lane marked is for the use of vehicles as indicated by the symbol or as indicated by a reservation sign. For example in this case, a high-occupancy vehicle.', '/testmate/assets/quiz/road_markings/sign_451.png', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What does road traffic sign 452 indicate?', 'Lane marked is for the use of vehicles as indicated by the symbol or as indicated by a reservation sign. For example in this case, a bus.', 'Indicates the direction of travel on a particular lane or road', 'There is a speed hump in the road', 'Do not drive, park or stop a vehicle in the lane unless it is a vehicle of the class indicated by the symbol or a reservation sign', 'A', 'Lane marked is for the use of vehicles as indicated by the symbol or as indicated by a reservation sign. For example in this case, a bus.', '/testmate/assets/quiz/road_markings/sign_452.png', 'image', '3');
