INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What is the main purpose of sign 479 (set item 1)?', 'Approaching vehicles from the rear to stop', 'Traffic approaching may proceed', 'Approaching vehicles from the front and rear to stop', 'Stop vehicle behind the stop line and remain stationary until green light signal is displayed, and ensure it is safe to proceed. If a pedestrian light is not provided, indicate to a pedestrian to cross the road if it is safe to do so. Act as for a 4-way stop and yield right of way to pedestrians crossing the road Stop vehicle behind the stop line and remain stationary until green light signal is displayed. If the vehicle is too close to a stop line when a yellow light signal is displayed and cannot stop safely, the driver may proceed with caution against such signal. If a pedestrian light is not provided, pedestrians may not cross the road until a green light is displayed and it is safe to do so. Proceed with caution and yield right of way to all pedestrians Proceed through or turn to the left or right in such junction, and yield right of way to other vehicles and pedestrians law- fully within such junction', 'D', 'Stop vehicle behind the stop line and remain stationary until green light signal is displayed, and ensure it is safe to proceed. If a pedestrian light is not provided, indicate to a pedestrian to cross the road if it is safe to do so. Act as for a 4-way stop and yield right of way to pedestrians crossing the road Stop vehicle behind the stop line and remain stationary until green light signal is displayed. If the vehicle is too close to a stop line when a yellow light signal is displayed and cannot stop safely, the driver may proceed with caution against such signal. If a pedestrian light is not provided, pedestrians may not cross the road until a green light is displayed and it is safe to do so. Proceed with caution and yield right of way to all pedestrians Proceed through or turn to the left or right in such junction, and yield right of way to other vehicles and pedestrians law- fully within such junction', '/testmate/assets/quiz/road_signals/sign_479.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'A driver sees sign 480. Which statement best describes what the sign means (set item 2)?', 'Stop vehicle behind the stop line and remain stationary until green light signal is displayed, and ensure it is safe to proceed. If a pedestrian light is not provided, indicate to a pedestrian to cross the road if it is safe to do so. Stop vehicle behind the stop line and remain stationary until green light signal is displayed. If the vehicle is too close to a stop line when a yellow light signal is displayed and cannot stop safely, the driver may proceed with caution against such signal. If a pedestrian light is not provided, pedestrians may not cross the road until a green light is displayed and it is safe to do so. Proceed through or turn to the left or right in such junction, and yield right of way to other vehicles and pedestrians law- fully within such junction. Proceed as movements are unopposed by other traffic facing a red light signal.', 'You must stop the vehicle and may not proceed until the signal ceases to flash and it is safe to do so', 'Approaching vehicles from the front to stop', 'Traffic approaching may proceed with caution', 'A', 'Stop vehicle behind the stop line and remain stationary until green light signal is displayed, and ensure it is safe to proceed. If a pedestrian light is not provided, indicate to a pedestrian to cross the road if it is safe to do so. Stop vehicle behind the stop line and remain stationary until green light signal is displayed. If the vehicle is too close to a stop line when a yellow light signal is displayed and cannot stop safely, the driver may proceed with caution against such signal. If a pedestrian light is not provided, pedestrians may not cross the road until a green light is displayed and it is safe to do so. Proceed through or turn to the left or right in such junction, and yield right of way to other vehicles and pedestrians law- fully within such junction. Proceed as movements are unopposed by other traffic facing a red light signal.', '/testmate/assets/quiz/road_signals/sign_480.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'Which action or meaning is associated with sign 481 (set item 3)?', 'Indicates to you that you shall not drive your vehicle in the lane over which the cross is displayed and that the lane is open to vehicles travelling in the opposite direction', 'Stop vehicle behind the stop line if intending to turn in the direction indicated by the red signal and remain stationary until green aspect is displayed, to allow movement in the direction of the arrow. Stop vehicle behind the stop line if intending to turn in the direction of the signal, proceed and yield right of way to all vehicles and pedestrians for whom a green disc light signal is displayed. Stop vehicle behind the stop line if intending to turn in the direction indicated by the yellow arrow light signal and remain stationary until a green light signal allowing the movement is displayed. Also act as for a steady yellow disc light signal. Proceed only in the direction indicated by the arrow. Move- ments are unopposed by other traffic facing a red light signal.', 'Approaching vehicles from the front and rear to stop', 'Pedal cyclist may not cross the road until the green pedal cycle light signal is displayed A pedal cyclist who has not yet commenced crossing the road, may not cross the road until the green pedal cycle light signal is displayed A Pedal cyclist who is within the pedestrian crossing is warned that the red pedal cycle light signal will follow shortly Pedal cyclist may cross the road while drivers must yield right of way to pedal cyclist crossing', 'B', 'Stop vehicle behind the stop line if intending to turn in the direction indicated by the red signal and remain stationary until green aspect is displayed, to allow movement in the direction of the arrow. Stop vehicle behind the stop line if intending to turn in the direction of the signal, proceed and yield right of way to all vehicles and pedestrians for whom a green disc light signal is displayed. Stop vehicle behind the stop line if intending to turn in the direction indicated by the yellow arrow light signal and remain stationary until a green light signal allowing the movement is displayed. Also act as for a steady yellow disc light signal. Proceed only in the direction indicated by the arrow. Move- ments are unopposed by other traffic facing a red light signal.', '/testmate/assets/quiz/road_signals/sign_481.png', 'image', '1');
