INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What is the main purpose of sign 488 (set item 10)?', 'Approaching vehicles from the front to stop', 'Indicates to you that you shall not drive your vehicle in the lane over which the cross is displayed and that the lane is open to vehicles travelling in the opposite direction', 'Stop vehicle behind the stop line and remain stationary until green light signal is displayed, and ensure it is safe to proceed. If a pedestrian light is not provided, indicate to a pedestrian to cross the road if it is safe to do so. Stop vehicle behind the stop line and remain stationary until green light signal is displayed. If the vehicle is too close to a stop line when a yellow light signal is displayed and cannot stop safely, the driver may proceed with caution against such signal. If a pedestrian light is not provided, pedestrians may not cross the road until a green light is displayed and it is safe to do so. Proceed through or turn to the left or right in such junction, and yield right of way to other vehicles and pedestrians law- fully within such junction. Proceed as movements are unopposed by other traffic facing a red light signal.', 'Traffic approaching must slow down', 'A', 'Approaching vehicles from the front to stop', '/testmate/assets/quiz/road_signals/sign_488.png', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'A driver sees sign 489. Which statement best describes what the sign means (set item 11)?', 'Approaching vehicles from the rear to stop', 'Stop vehicle behind the stop line and remain stationary until green light signal is displayed, and ensure it is safe to proceed. If a pedestrian light is not provided, indicate to a pedestrian to cross the road if it is safe to do so. Stop vehicle behind the stop line and remain stationary until green light signal is displayed. If the vehicle is too close to a stop line when a yellow light signal is displayed and cannot stop safely, the driver may proceed with caution against such signal. If a pedestrian light is not provided, pedestrians may not cross the road until a green light is displayed and it is safe to do so. Proceed through or turn to the left or right in such junction, and yield right of way to other vehicles and pedestrians law- fully within such junction. Proceed as movements are unopposed by other traffic facing a red light signal.', 'Traffic approaching may proceed', 'You must stop the vehicle and may not proceed until the signal ceases to flash and it is safe to do so', 'A', 'Approaching vehicles from the rear to stop', '/testmate/assets/quiz/road_signals/sign_489.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'Which action or meaning is associated with sign 490 (set item 12)?', 'Traffic approaching may proceed', 'Pedal cyclist may not cross the road until the green pedal cycle light signal is displayed A pedal cyclist who has not yet commenced crossing the road, may not cross the road until the green pedal cycle light signal is displayed A Pedal cyclist who is within the pedestrian crossing is warned that the red pedal cycle light signal will follow shortly Pedal cyclist may cross the road while drivers must yield right of way to pedal cyclist crossing', 'Approaching vehicles from the front to stop', 'Approaching vehicles from the front and rear to stop', 'D', 'Approaching vehicles from the front and rear to stop', '/testmate/assets/quiz/road_signals/sign_490.png', 'image', '2');
