INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'A driver sees sign 492. Which statement best describes what the sign means (set item 14)?', 'Stop vehicle behind the stop line if intending to turn in the direction indicated by the red signal and remain stationary until green aspect is displayed, to allow movement in the direction of the arrow. Stop vehicle behind the stop line if intending to turn in the direction of the signal, proceed and yield right of way to all vehicles and pedestrians for whom a green disc light signal is displayed. Stop vehicle behind the stop line if intending to turn in the direction indicated by the yellow arrow light signal and remain stationary until a green light signal allowing the movement is displayed. Also act as for a steady yellow disc light signal. Proceed only in the direction indicated by the arrow. Move- ments are unopposed by other traffic facing a red light signal.', 'Approaching vehicles from the front and rear to stop', 'Stop vehicle behind the stop line and remain stationary until green light signal is displayed, and ensure it is safe to proceed. If a pedestrian light is not provided, indicate to a pedestrian to cross the road if it is safe to do so. Stop vehicle behind the stop line and remain stationary until green light signal is displayed. If the vehicle is too close to a stop line when a yellow light signal is displayed and cannot stop safely, the driver may proceed with caution against such signal. If a pedestrian light is not provided, pedestrians may not cross the road until a green light is displayed and it is safe to do so. Proceed through or turn to the left or right in such junction, and yield right of way to other vehicles and pedestrians law- fully within such junction. Proceed as movements are unopposed by other traffic facing a red light signal.', 'Traffic approaching may proceed', 'D', 'Traffic approaching may proceed', '/testmate/assets/quiz/road_signals/sign_492.png', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'Which action or meaning is associated with sign 493 (set item 15)?', 'Approaching vehicles from the front to stop', 'Approaching vehicles from the front to stop', 'Stop vehicle behind the stop line and remain stationary until green light signal is displayed, and ensure it is safe to proceed. If a pedestrian light is not provided, indicate to a pedestrian to cross the road if it is safe to do so. Stop vehicle behind the stop line and remain stationary until green light signal is displayed. If the vehicle is too close to a stop line when a yellow light signal is displayed and cannot stop safely, the driver may proceed with caution against such signal. If a pedestrian light is not provided, pedestrians may not cross the road until a green light is displayed and it is safe to do so. Proceed through or turn to the left or right in such junction, and yield right of way to other vehicles and pedestrians law- fully within such junction. Proceed as movements are unopposed by other traffic facing a red light signal.', 'Traffic approaching must slow down', 'A', 'Approaching vehicles from the front to stop', '/testmate/assets/quiz/road_signals/sign_493.png', 'image', '2');
