INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'Which side of the road must a driver normally drive on?', 'The left side', 'The right side', 'The shoulder only', 'Any side', 'A', 'The manual states: drive only on the left side of the road.', '', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'When may a driver move onto the road to the right?', 'When it can be done safely and is not prohibited, or when directed/permitted', 'Whenever the road is empty', 'Only at night', 'Only on a freeway', 'A', 'The manual lists safety, signs, traffic-officer directions and overtaking as circumstances allowing movement to the right.', '', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What is prohibited on a divided road except through an opening or crossover/intersection?', 'Driving on, over, across or within an intervening barrier/space', 'Driving on the left side', 'Using indicators', 'Using mirrors', 'A', 'The manual prohibits crossing intervening spaces/barriers except through permitted openings/crossovers/intersections.', '', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'At what places is overtaking prohibited?', 'Near a summit of a rise, a curve, restricted view, or where signs/markings prohibit it', 'Only at traffic lights', 'Only in urban areas', 'Only on gravel roads', 'A', 'These are the places specifically listed in the manual.', '', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What should a driver do before overtaking another vehicle?', 'Give a signal', 'Switch off headlights', 'Sound the horn continuously', 'Stop completely', 'A', 'The manual says to give a signal before overtaking.', '', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'On which side should a vehicle normally pass the vehicle being overtaken?', 'On the right, if safe', 'On the left always', 'On the shoulder', 'On the pavement', 'A', 'The manual states to pass on the right if it is safe to do so.', '', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'When may a driver move back to the left after overtaking?', 'When safely clear of the vehicle being passed', 'Immediately after signalling', 'Before passing the vehicle', 'Only after stopping', 'A', 'The manual says not to move back until safely clear.', '', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What should a driver do when being overtaken?', 'Do not accelerate until the other vehicle has passed', 'Accelerate immediately', 'Move to the right', 'Stop in the lane', 'A', 'The manual states not to accelerate until the other vehicle has passed.', '', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'How should a driver pass a stationary bus?', 'With due care for people approaching or leaving the bus', 'At maximum speed', 'On the pavement', 'Without observing pedestrians', 'A', 'The manual requires due care for persons approaching or leaving a stationary bus.', '', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What is required when approaching a pedestrian crossing?', 'Yield right of way as required to pedestrians crossing', 'Always accelerate', 'Ignore pedestrians', 'Park on the crossing', 'A', 'The road-sign/marking rules require yielding to pedestrians in the situations described.', '', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'Where is stopping prohibited near a pedestrian crossing according to the manual?', 'Within 9 metres of the pedestrian crossing', 'Within 1 metre only', 'Within 50 metres', 'Only directly on the crossing', 'A', 'The manual lists within 9 m of the pedestrian crossing among prohibited stopping places.', '', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'How close to an intersection is stopping prohibited?', 'Within 5 metres', 'Within 1 metre', 'Within 20 metres', 'Only at the centre', 'A', 'The manual lists within 5 m of any intersection.', '', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'How close to a fire hydrant is parking prohibited?', 'Within 1.5 metres', 'Within 10 metres', 'Within 50 metres', 'Only directly over it', 'A', 'The manual lists within 1.5 m of a fire hydrant.', '', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What should a driver do when a traffic officer signals a stop?', 'Stop', 'Continue if the road is clear', 'Reverse immediately', 'Change lanes without stopping', 'A', 'Stopping is compulsory when required by a traffic officer.', '', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What should a driver do when approaching a State motorcade?', 'Stop and remain stationary until instructed to proceed', 'Overtake it', 'Follow closely', 'Sound the horn and pass', 'A', 'The manual requires stopping and remaining stationary until instructed.', '', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What is a compulsory reason to stop after an accident?', 'The vehicle is involved in an accident', 'The vehicle is low on fuel', 'The driver is late', 'The road is empty', 'A', 'The manual lists stopping when involved in an accident as compulsory.', '', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What is a driver required to do if involved in an accident with injury?', 'Find out the nature and extent of injury and render assistance capable of being rendered', 'Leave immediately', 'Move the vehicle without marking its position', 'Take no action', 'A', 'These duties are expressly listed in the manual.', '', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'Within what period must an accident generally be reported when the stated conditions apply?', 'Within 24 hours', 'Within 7 days', 'Within 30 days', 'Only at licence renewal', 'A', 'The manual specifies reporting within 24 hours at a police station or traffic officer’s office unless the stated exceptions apply.', '', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What should a driver do when approaching a railway crossing?', 'Obey the applicable signs/signals and proceed only when safe', 'Ignore the crossing', 'Accelerate without checking', 'Park on the tracks', 'A', 'The manual’s rules require compliance with road traffic signs/signals and safe movement.', '', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What should a driver do before turning?', 'Signal and make the turn safely according to the road rules', 'Turn without signalling', 'Stop in every case', 'Use the shoulder only', 'A', 'The manual includes signalling and safe turning procedures among the rules of the road.', '', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What is the purpose of a hand signal?', 'To communicate a driver’s intended movement to other road users', 'To increase speed', 'To switch headlights', 'To select a gear', 'A', 'The manual describes prescribed hand signals for movements such as stopping and turning.', '', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What should a driver do when overtaking a heavy vehicle?', 'Grip the steering wheel more firmly to counter sudden wind-pressure changes', 'Release the steering wheel', 'Drive onto the pavement', 'Brake sharply beside it', 'A', 'The manual specifically advises gripping the steering wheel more firmly when passing a heavy vehicle.', '', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'When may a driver use the road to the right on a divided road?', 'When directed or permitted by a sign or traffic officer, subject to the rules', 'Whenever desired', 'Only when parked', 'Only during rain', 'A', 'The manual gives these exceptions.', '', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What is the general rule for driving on a divided road?', 'Drive only on the left side unless directed/permitted otherwise', 'Drive in the middle', 'Use the right side only', 'Drive on either side', 'A', 'This is the stated general rule.', '', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What must a driver do if a road traffic sign prohibits overtaking?', 'Do not overtake there', 'Overtake slowly', 'Overtake only motorcycles', 'Use the shoulder to overtake', 'A', 'The manual expressly prohibits overtaking where a sign or marking prohibits it.', '', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What should a driver do before moving back after overtaking?', 'Ensure the vehicle being passed is safely clear', 'Signal only after moving back', 'Stop in the right lane', 'Accelerate into the left lane immediately', 'A', 'The manual says not to move back until safely clear.', '', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What should a driver do if another vehicle is overtaking?', 'Do not accelerate and do not move onto the right-hand side', 'Accelerate and move right', 'Brake hard immediately', 'Drive onto the pavement', 'A', 'These are stated duties when being overtaken.', '', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'Why must drivers take care when passing a stationary bus?', 'People may be approaching or leaving the bus', 'The bus always has priority to reverse', 'The bus is a traffic signal', 'It is always illegal to pass', 'A', 'The manual specifically cites the safety of people approaching or leaving the bus.', '', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What is the rule about driving through an intervening barrier on a divided road?', 'Do not do so except at permitted openings/crossovers/intersections', 'Always do so if traffic is light', 'Only do so at night', 'Do so when overtaking', 'A', 'The manual restricts crossing such barriers to specified openings/crossovers/intersections.', '', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What should a driver do when a traffic officer gives a direction?', 'Comply with the direction', 'Ignore it if the road is clear', 'Wait for another driver', 'Only comply at night', 'A', 'The rules include compliance with directions of a traffic officer.', '', 'image', '3');
