INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What must a driver do immediately after an accident involving injury, death, property or animal damage?', 'Stop the vehicle', 'Leave the scene', 'Remove all evidence', 'Continue driving', 'A', 'The manual says immediately stop the vehicle.', '', 'image', '1');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What must the driver find out after such an accident?', 'The nature and extent of any injury', 'Only the weather', 'Only the fuel level', 'Only the road name', 'A', 'The manual requires finding out the nature and extent of injury.', '', 'image', '1');
