INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What vehicle information may have to be supplied after an accident?', 'The owner’s name/address and, for a motor vehicle, the licence mark and number', 'Only the engine size', 'Only the fuel type', 'Only the tyre brand', 'A', 'These details are listed in the accident duties.', '', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'When must an accident generally be reported?', 'Within 24 hours', 'Within 48 hours', 'Within 7 days', 'At the next licence renewal', 'A', 'The manual specifies within 24 hours under the stated conditions.', '', 'image', '2');
