INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What must be true of lamps fitted to a motor vehicle operated on a road?', 'They must be undamaged, properly secured and capable of being switched on at all times', 'They may be broken', 'Only one lamp must work', 'They must be removed in daylight', 'A', 'These are the stated lamp requirements.', '', 'image', '2');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'When should the main beam be dipped?', 'When it could cause dangerous glare to oncoming traffic', 'Only when parked', 'Only on gravel roads', 'Never', 'A', 'The manual requires dipping the main beam when it could cause dangerous glare.', '', 'image', '2');
