INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'How must a protective helmet fit?', 'Properly, with the chin strap properly fastened', 'Loosely', 'Without a chin strap', 'Only on the passenger', 'A', 'The manual specifies proper fit and a properly fastened chin strap.', '', 'image', '3');
