INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'How far may goods project to either side?', '450 mm', '900 mm', '600 mm', '300 mm', 'A', 'The manual lists 450 mm to either side.', '', 'image', '3');
INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What is required of seatbelts fitted to a motor vehicle?', 'They must be in good working order', 'They may be removed while driving', 'They need work only at night', 'They are optional for every adult', 'A', 'The manual requires fitted seatbelts to be in good working order.', '', 'image', '3');
