INSERT INTO questions (topic_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, image_path, file_type, quiz_set) VALUES (@topic_id, 'What is the maximum overall height of a double-decker bus according to the manual?', '4.65 m', '4.3 m', '2.5 m', '12.5 m', 'A', 'The manual lists 4.65 m for a double-decker bus.', '', 'image', '3');
